def relabeled_clone(self, relabels):
    # Bug fix: Return a new instance of the class with relabels applied
    new_instance = self.__class__()
    # Apply relabels to the new instance
    # Assuming relabels is a dictionary with keys as original labels and values as new labels
    for key, value in relabels.items():
        if hasattr(self, key):
            setattr(new_instance, value, getattr(self, key))
    return new_instance
